/**
 * Rule: navigation/href-javascript-void
 * Satisfies: wcag22:4.1.2, wcag21:4.1.2, wcag22:2.1.1, wcag21:2.1.1
 * Spec: https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * > For all user interface components (including but not limited to:
 * > form elements, links and components generated by scripts), the
 * > name and role can be programmatically determined; states,
 * > properties, and values that can be set by the user can be
 * > programmatically set; and notification of changes to these items
 * > is available to user agents, including assistive technologies.
 *
 * Source: https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * An `<a>` element with a non-navigating href — `href="javascript:…"`
 * in any of its forms (`javascript:void(0)`, `javascript:;`,
 * `javascript:`) or a bare fragment `href="#"` — behaves like a
 * button but announces as a link. Assistive technology says "link,"
 * the user expects navigation, nothing navigates. The semantic role
 * is wrong.
 *
 * Separate from `navigation/link-no-href` (which targets
 * `<a onClick>` without any real navigation target). This rule
 * targets the href VALUE itself, regardless of whether an onClick
 * is attached — an `<a href="javascript:void(0)">` is semantically
 * broken even without an event handler, because the anchor promises
 * navigation the href can never deliver.
 *
 * The fix is almost always the same: if the control performs an
 * action, use `<button type="button">` and style it to look like a
 * link if the visual treatment matters. If it performs navigation,
 * put the real URL in `href` instead of wiring it through a
 * javascript: scheme.
 */

import { defineRule } from "../../api/plugin.ts";
import {
  findHtmlElementsByTag,
  findJsxElementsByTag,
  getHtmlAttribute,
  getJsxAttribute,
} from "../../engine/ast-helpers.ts";
import type { HtmlDocument, TsxModule } from "../../types/ast.ts";

type PlaceholderKind = "javascript-scheme" | "bare-fragment";

/**
 * Classifies a raw href string as a non-navigating placeholder, or
 * returns `null` when the value is either a real navigation target or
 * a legitimate fragment link to a same-document id.
 *
 * Whitespace is tolerated aggressively — real-world placeholders appear
 * as `"javascript:void(0)"`, `"javascript: void(0)"`, `"  #  "`,
 * `"JAVASCRIPT:;"`. The scheme comparison is case-insensitive because
 * URL schemes are case-insensitive per RFC 3986 §3.1 and browsers treat
 * them that way.
 *
 * What this function does NOT flag (handled elsewhere or legitimately
 * navigating):
 *
 *   - `""` and whitespace-only — handled by `navigation/link-no-href`
 *     when combined with an onClick. A bare empty href without onClick
 *     is a separate concern (element is inert).
 *   - `"#fragment-id"` — real in-page navigation; browser scrolls to
 *     and focuses the matching id. Silent.
 *   - Any other scheme (`"mailto:"`, `"tel:"`, `"/path"`, `"https://…"`) —
 *     real navigation of some flavor. Silent.
 */
function classifyPlaceholder(value: string | null): PlaceholderKind | null {
  if (value === null) return null;
  const trimmed = value.trim();
  if (trimmed === "") return null; // link-no-href's domain, not ours.
  if (trimmed === "#") return "bare-fragment";
  // Any `javascript:` scheme, regardless of what follows. Examples:
  //   javascript:void(0)   javascript:void 0   javascript:;
  //   javascript:          javascript:alert(1)
  // Bare `"javascript"` (no colon) is technically a relative path, not a
  // scheme — but in practice it's always an author typo meant to be
  // `javascript:void(0)`. Flag it; the fix suggestion is identical.
  const lowered = trimmed.toLowerCase();
  if (lowered === "javascript") return "javascript-scheme";
  if (/^javascript\s*:/i.test(trimmed)) return "javascript-scheme";
  return null;
}

export const rule = defineRule({
  id: "navigation/href-javascript-void",
  satisfies: ["wcag22:4.1.2", "wcag21:4.1.2", "wcag22:2.1.1", "wcag21:2.1.1"],
  severity: "error",
  scope: "node",
  fixClass: "verify-in-source",
  appliesTo: {
    fileExtensions: [".html", ".htm", ".tsx", ".jsx"],
  },
  docs: {
    description:
      "<a> elements with href='javascript:…' or bare href='#' announce as links but do not navigate. Use <button type=\"button\"> for actions, or put a real URL in href for navigation.",
    rationale:
      "Assistive technology decides how to announce a control from its role: `<a>` with an href maps to the link role. When the href is `javascript:void(0)`, `javascript:;`, or bare `#`, the browser treats the element as a link but nothing navigates — the user hears 'link,' activates it, and nothing happens. The semantic role (link) contradicts the runtime behavior (button-like action or no-op), breaking WCAG 4.1.2 Name, Role, Value. Static detection is reliable because the href attribute's string value is the full signal.",
    goodExample: `<button type="button" onClick={handleClick}>Toggle menu</button>`,
    badExample: `<a href="javascript:void(0)" onClick={handleClick}>Toggle menu</a>`,
    normativeQuote:
      "For all user interface components … the name and role can be programmatically determined.",
    references: [
      "https://www.w3.org/TR/WCAG22/#name-role-value",
      "https://www.w3.org/TR/WCAG22/#keyboard",
      "https://html.spec.whatwg.org/#the-a-element",
    ],
  },
  check(ctx) {
    if (ctx.language === "html") {
      checkHtml(ctx.ast as HtmlDocument, (v) => ctx.emit(v));
    } else if (
      ctx.language === "tsx" ||
      ctx.language === "jsx" ||
      ctx.language === "ts" ||
      ctx.language === "js"
    ) {
      checkJsx(ctx.ast as TsxModule, (v) => ctx.emit(v));
    }
  },
});

type Emit = (v: {
  severity: "error" | "warning" | "info";
  location: { filePath: string; line: number; column: number };
  message: string;
  suggestion: string;
}) => void;

function checkHtml(doc: HtmlDocument, emit: Emit): void {
  for (const anchor of findHtmlElementsByTag(doc, "a")) {
    const hrefValue = getHtmlAttribute(anchor, "href");
    const kind = classifyPlaceholder(hrefValue);
    if (!kind) continue;
    emit(buildViolation(anchor.loc.start, kind, hrefValue ?? ""));
  }
}

function checkJsx(module: TsxModule, emit: Emit): void {
  for (const anchor of findJsxElementsByTag(module, "a")) {
    const attr = getJsxAttribute(anchor, "href");
    if (!attr?.value) continue;
    // Expression-form `href={…}` is opaque at static time — the value
    // could be a real URL, a placeholder string, or anything else. Per
    // the AI-first consumer model, the tool's job is to point at
    // deterministic evidence; opaque expressions don't qualify. The
    // agent can read the source if the call site looks suspicious.
    if (attr.value.kind !== "StringLiteral") continue;
    const kind = classifyPlaceholder(attr.value.value);
    if (!kind) continue;
    emit(buildViolation(anchor.loc.start, kind, attr.value.value));
  }
}

function buildViolation(
  loc: { line: number; column: number },
  kind: PlaceholderKind,
  rawHref: string,
): {
  severity: "error";
  location: { filePath: string; line: number; column: number };
  message: string;
  suggestion: string;
} {
  return {
    severity: "error",
    location: { filePath: "", line: loc.line, column: loc.column },
    message: buildMessage(kind, rawHref),
    suggestion: buildSuggestion(kind, rawHref),
  };
}

function buildMessage(kind: PlaceholderKind, rawHref: string): string {
  const display = rawHref.length > 60 ? `${rawHref.slice(0, 60)}…` : rawHref;
  if (kind === "javascript-scheme") {
    return `<a href="${display}"> uses a javascript: scheme — the anchor announces as a link but does not navigate, contradicting its role.`;
  }
  return `<a href="#"> has no fragment target — the anchor announces as a link but navigates nowhere.`;
}

function buildSuggestion(kind: PlaceholderKind, rawHref: string): string {
  const display = rawHref.length > 60 ? `${rawHref.slice(0, 60)}…` : rawHref;
  if (kind === "javascript-scheme") {
    return `change \`<a href="${display}">\` to \`<button type="button">\` — this control does not navigate, so it should announce as a button, not a link. If you need anchor-style visuals, style the <button> with CSS instead of giving an anchor a non-URL href. If the handler actually navigates somewhere, put that URL directly in href and drop the javascript: wrapper.`;
  }
  return `change \`<a href="#">\` to \`<button type="button">\` — a bare \`#\` href announces as a link but navigates nowhere. If the control triggers an action, a <button> is the correct role. If it should navigate to an in-page section, use \`href="#section-id"\` pointing at an actual id on the page.`;
}
